css:
body{font-family:ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI Variable Display","Segoe UI",Helvetica,Arial,sans-serif;}
.chat-markdown code,.chat-markdown-codeblock{font-family:"SFMono-Regular",Menlo,Consolas,"PT Mono","Liberation Mono",Courier,monospace;}
:root:not(.dark) .chat-markdown :not(pre)>code{color:#EB5757;background:rgba(135,131,120,.15);border-radius:4px;padding:.2em .4em;}
.dark .chat-markdown :not(pre)>code{color:#FF7369;background:rgba(135,131,120,.15);border-radius:4px;padding:.2em .4em;}
[data-thread-item]{border-radius:6px!important;}
[data-slot="button"],[data-slot="input"],[data-slot="select-trigger"]{border-radius:6px!important;}
[data-slot="composer-host"]{border-radius:12px!important;border:1px solid var(--border)!important;box-shadow:0 1px 2px rgba(15,15,15,.04),0 4px 12px rgba(15,15,15,.04)!important;}
[data-user-message-bubble]{border-radius:10px!important;}
.chat-markdown-codeblock{border-radius:4px!important;border:none;}
:root:not(.dark) [data-slot="dialog-popup"],:root:not(.dark) [data-slot="popover-popup"],:root:not(.dark) [data-slot="menu-popup"]{border-radius:10px!important;border:none!important;box-shadow:rgba(15,15,15,.05) 0 0 0 1px,rgba(15,15,15,.1) 0 3px 6px,rgba(15,15,15,.2) 0 9px 24px!important;}
.dark [data-slot="dialog-popup"],.dark [data-slot="popover-popup"],.dark [data-slot="menu-popup"]{border-radius:10px!important;border:none!important;box-shadow:rgba(255,255,255,.094) 0 0 0 1px,rgba(0,0,0,.2) 0 3px 6px,rgba(0,0,0,.4) 0 9px 24px!important;}
[data-slot="tooltip-popup"]{border-radius:4px!important;}
svg.lucide{stroke-width:1.75;}
button.bg-message-action:disabled{background:color-mix(in srgb,var(--foreground) 10%,transparent)!important;color:var(--muted-foreground)!important;opacity:1!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked]{background:#E3E2E0!important;box-shadow:none!important;}
.dark [data-slot="switch"][data-unchecked]{background:#3F3F3F!important;box-shadow:none!important;}
[data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
[data-slot="switch"][data-checked]{background:#2383E2!important;box-shadow:none!important;}
[data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
::-webkit-scrollbar{width:10px;height:10px;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--foreground) 14%,transparent);border-radius:999px;border:2px solid transparent;background-clip:padding-box;}
::-webkit-scrollbar-thumb:hover{background-color:color-mix(in srgb,var(--foreground) 24%,transparent);}
::selection{background:rgba(35,131,226,.28);}
